import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [stack, setStack] = useState(["Нүүр"]);
  const current = stack[stack.length - 1];

  const push = (s) => setStack((prev) => [...prev, s]);
  const pop = () => setStack((prev) => (prev.length > 1 ? prev.slice(0, -1) : prev));

  return (
    <View style={styles.screen}>
      <Text nativeID="cur" style={styles.h}>{current}</Text>
      <Text nativeID="depth">Гүн: {stack.length}</Text>
      <Pressable nativeID="toCat" style={styles.btn} onPress={() => push("Каталог")}>
        <Text style={styles.btnText}>Каталог руу</Text>
      </Pressable>
      <Pressable nativeID="toItem" style={styles.btn} onPress={() => push("Бараа")}>
        <Text style={styles.btnText}>Бараа руу</Text>
      </Pressable>
      <Pressable nativeID="back" style={styles.gray} onPress={pop}>
        <Text style={styles.btnText}>← Буцах</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  h: { fontSize: 26, fontWeight: "bold" },
  btn: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12, alignItems: "center" },
  gray: { backgroundColor: "#64748b", padding: 14, borderRadius: 12, alignItems: "center" },
  btnText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
